(() => {
  'use strict';
  const DB_NAME='AgendaFinanzasLocal', STORE='records', LIMIT=20*1024*1024;
  const root=document.querySelector('#financeView');
  if(!root)return;
  const $=(selector,base=root)=>base.querySelector(selector);
  const safe=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const dateObj=s=>{const [y,m,d]=String(s||'').split('-').map(Number);return new Date(y||2000,(m||1)-1,d||1);};
  const dateText=date=>new Intl.DateTimeFormat(window.AgendaI18n?.locale||'es-MX',{day:'numeric',month:'short',year:'numeric'}).format(dateObj(date));
  const dateNode=date=>`<time data-locale-date="${safe(date)}">${safe(dateText(date))}</time>`;
  const money=new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'});
  const num=n=>Number.isFinite(Number(n))?Number(n):0;
  const id=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const cats=['Alimentación','Vivienda','Servicios','Transporte','Salud','Educación','Entretenimiento','Compras personales','Impuestos','Otros'];
  let db, records=[], tab='resumen', period=today().slice(0,7), notice='';
  const paymentCategories=['Electricidad','Agua','Internet','Telefonía','Renta','Tarjetas de crédito','Préstamos','Seguros','Suscripciones','Impuestos','Otros'];
  const paymentFrequencies=[['once','Único'],['weekly','Semanal'],['biweekly','Quincenal'],['monthly','Mensual'],['bimonthly','Bimestral'],['quarterly','Trimestral'],['semiannual','Semestral'],['annual','Anual']];
  let reminderTimer=0, reminderCheckBusy=false, reminderListenersReady=false, editingPaymentId=null;
  const monthOf=d=>String(d||'').slice(0,7);
  const monthStart=()=>`${period}-01`;
  const inMonth=r=>monthOf(r.date)===period;
  const sum=(items,fn)=>items.reduce((acc,item)=>acc+fn(item),0);
  const all=type=>records.filter(r=>r.type===type);
  const tx=()=>records.filter(r=>r.type==='transaction');
  const debtPayments=()=>all('debtPayment');
  const savingsMoves=()=>all('savingsMove');
  const incomes=()=>tx().filter(r=>r.direction==='income');
  const expenses=()=>tx().filter(r=>r.direction==='expense');
  const val=r=>num(r.amount);
  const financials=()=>{
    const incoming=incomes().filter(inMonth), outgoing=expenses().filter(inMonth);
    const paidDebt=debtPayments().filter(inMonth);
    const savingsOut=savingsMoves().filter(r=>inMonth(r)&&r.direction==='deposit');
    const linkedPayments=new Set(outgoing.map(r=>r.debtPaymentId).filter(Boolean));
    const income=sum(incoming,val), debtTotal=sum(paidDebt,val), expensesTotal=sum(outgoing,val)+sum(paidDebt.filter(p=>!linkedPayments.has(p.id)),val), saved=sum(savingsOut,val);
    const nonDebtExpenses=sum(outgoing.filter(r=>!r.debtPaymentId),val);
    return {income,expenses:expensesTotal,debtTotal,saved,balance:income-expensesTotal,available:income-nonDebtExpenses-debtTotal-saved};
  };
  function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const database=req.result;if(!database.objectStoreNames.contains(STORE)){const store=database.createObjectStore(STORE,{keyPath:'id'});store.createIndex('type','type');store.createIndex('date','date',{unique:false});}};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  function readAll(){return new Promise((resolve,reject)=>{const req=db.transaction(STORE,'readonly').objectStore(STORE).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);});}
  function commit(next){return new Promise((resolve,reject)=>{const t=db.transaction(STORE,'readwrite'),s=t.objectStore(STORE);s.clear();for(const r of next)s.put(r);t.oncomplete=()=>{records=next;resolve();};t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('No se pudieron guardar los datos financieros.'));});}
  const moneyFormat=n=>money.format(num(n));
  function options(values,selected=''){return values.map(x=>`<option value="${safe(x)}" ${x===selected?'selected':''}>${safe(x)}</option>`).join('');}
  function card(label,value,detail=''){return `<article class="panel finance-metric"><div class="eyebrow">${safe(label)}</div><strong>${moneyFormat(value)}</strong>${detail?`<small>${safe(detail)}</small>`:''}</article>`;}
  function countCard(label,value){return `<article class="panel finance-metric"><div class="eyebrow">${safe(label)}</div><strong>${Number(value)||0}</strong></article>`;}
  function field(label,name,type='text',value='',attrs=''){return `<label>${safe(label)}<input name="${safe(name)}" type="${type}" value="${safe(value)}" ${attrs} required></label>`;}
  function empty(text){return `<div class="finance-empty">${safe(text)}</div>`;}
  function dataRows(items){return items.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(r=>`<div class="finance-row">${dateNode(r.date)}<div><strong>${safe(r.concept||r.name||r.title||'Movimiento')}</strong><small>${safe(r.category||r.kind||r.note||'')} ${r.status==='pending'?'· Pendiente':''}</small></div><b class="${r.direction==='income'?'finance-positive':r.direction==='expense'?'finance-negative':''}">${r.direction==='income'?'+':r.direction==='expense'?'−':''}${moneyFormat(r.amount)}</b><button type="button" class="finance-delete" data-delete="${safe(r.id)}" aria-label="Eliminar">×</button></div>`).join('')||empty('No hay movimientos para mostrar.');}
  function transactionForm(){return `<form class="panel finance-form" id="transactionForm"><h3>Registrar movimiento</h3><div class="finance-form-grid">${`<label>Tipo<select name="direction"><option value="expense">Gasto</option><option value="income">Ingreso</option></select></label>`}${field('Concepto','concept','text','', 'maxlength="120"')}${field('Importe','amount','number','','min="0.01" step="0.01"')}${field('Fecha','date','date',today())}<label>Categoría<select name="category">${options(cats,'Otros')}</select></label><label>Clasificación<select name="kind"><option value="variable">Variable</option><option value="fixed">Fijo</option><option value="extraordinary">Extraordinario</option></select></label><label>Forma de pago<select name="paymentMethod">${options(['Efectivo','Débito','Crédito','Transferencia','Domiciliación','Otro'],'Efectivo')}</select></label><label>Estado<select name="status"><option value="paid">Pagado/recibido</option><option value="pending">Pendiente</option></select></label><label class="finance-wide">Observaciones<textarea name="notes" maxlength="500" rows="2"></textarea></label></div><button class="save-btn" type="submit">Guardar movimiento <span>✓</span></button></form>`;}
  function renderSummary(){const f=financials(),prev=new Date(`${period}-01T12:00:00`);prev.setMonth(prev.getMonth()-1);const previous=prev.toISOString().slice(0,7);const beforeIncome=sum(incomes().filter(r=>monthOf(r.date)===previous),val),beforeExpense=sum(expenses().filter(r=>monthOf(r.date)===previous),val);const due=all('debt').filter(d=>num(d.balance)>0).sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||'')).slice(0,5);const savings=all('goal');return `<div class="finance-toolbar"><div><div class="eyebrow">CONTROL PERSONAL · SOLO EN ESTE DISPOSITIVO</div><h2>Resumen financiero</h2></div><label class="finance-period">Mes<input type="month" data-period value="${safe(period)}"></label></div><div class="finance-metrics">${card('INGRESOS DEL MES',f.income,`Mes anterior: ${moneyFormat(beforeIncome)}`)}${card('GASTOS DEL MES',f.expenses,`Mes anterior: ${moneyFormat(beforeExpense)}`)}${card('BALANCE DEL MES',f.balance,'Ingresos menos gastos registrados')}${card('DINERO DISPONIBLE',f.available,'Balance menos abonos y aportaciones')}${card('DEUDAS PENDIENTES',sum(all('debt'),d=>num(d.balance)))}${card('AHORRO ACUMULADO',sum(savings,g=>num(g.balance)))}${card('ABONOS A DEUDA ESTE MES',f.debtTotal)}${card('APORTADO ESTE MES',f.saved)}</div><div class="finance-columns"><article class="panel finance-block"><div class="section-head"><div><div class="eyebrow">ACTIVIDAD RECIENTE</div><h3>Movimientos del mes</h3></div></div>${dataRows(tx().filter(inMonth))}</article><article class="panel finance-block"><div class="eyebrow">PRÓXIMOS VENCIMIENTOS</div><h3>Deudas por pagar</h3>${due.length?due.map(d=>`<div class="finance-row"><span>${d.dueDate?dateNode(d.dueDate):'Sin fecha'}</span><div><strong>${safe(d.name)}</strong><small>${d.dueDate&&d.dueDate<today()?'VENCIDA · ':''}Saldo pendiente · ${moneyFormat(d.balance)}</small></div><b>${moneyFormat(d.monthlyPayment||0)}</b></div>`).join(''):empty('No tienes deudas pendientes registradas.')}</article></div>${transactionForm()}`;}
  function renderTransactions(){const items=tx().sort((a,b)=>b.date.localeCompare(a.date));return `<div class="finance-toolbar"><div><div class="eyebrow">INGRESOS Y GASTOS</div><h2>Movimientos</h2></div><label class="finance-period">Mes<input type="month" data-period value="${safe(period)}"></label></div><div class="finance-metrics">${card('INGRESOS DEL MES',sum(items.filter(r=>inMonth(r)&&r.direction==='income'),val))}${card('GASTOS DEL MES',sum(items.filter(r=>inMonth(r)&&r.direction==='expense'),val))}${card('INGRESOS DEL AÑO',sum(items.filter(r=>r.date.startsWith(period.slice(0,4))&&r.direction==='income'),val))}${card('GASTOS DEL AÑO',sum(items.filter(r=>r.date.startsWith(period.slice(0,4))&&r.direction==='expense'),val))}</div>${transactionForm()}<article class="panel finance-block"><div class="finance-filter"><h3>Historial</h3><label>Buscar<input type="search" data-search placeholder="Concepto"></label><label>Categoría<select data-category><option value="">Todas</option>${options(cats)}</select></label><label>Tipo<select data-direction><option value="">Todos</option><option value="income">Ingresos</option><option value="expense">Gastos</option></select></label><label>Desde<input type="date" data-from></label><label>Hasta<input type="date" data-to></label></div><div id="financeTransactions">${dataRows(items)}</div></article>`;}
  function renderDebts(){const debts=all('debt');return `<div class="finance-toolbar"><div><div class="eyebrow">SALDOS Y ABONOS</div><h2>Adeudos y deudas</h2></div><div class="finance-total">Pendiente ${moneyFormat(sum(debts,d=>num(d.balance)))}</div></div><form class="panel finance-form" id="debtForm"><h3>Registrar deuda</h3><div class="finance-form-grid">${field('Acreedor o institución','name','text','','maxlength="100"')}${field('Concepto','concept','text','','maxlength="120"')}${field('Importe original','original','number','','min="0.01" step="0.01"')}${field('Saldo pendiente','balance','number','','min="0" step="0.01"')}${field('Fecha de contratación','startDate','date',today())}<label>Próximo vencimiento<input name="dueDate" type="date"></label>${field('Mensualidad','monthlyPayment','number','0','min="0" step="0.01"')}<label>Frecuencia<select name="frequency">${options(['Mensual','Quincenal','Semanal','Anual','Único'],'Mensual')}</select></label>${field('Tasa anual (%)','interest','number','0','min="0" max="1000" step="0.01"')}${field('Pagos pendientes','paymentsLeft','number','0','min="0" step="1"')}<label>Estado<select name="status"><option value="active">Activa</option><option value="paused">Pausada</option><option value="paid">Liquidada</option></select></label><label class="finance-wide">Observaciones<textarea name="notes" maxlength="500" rows="2"></textarea></label></div><button class="save-btn" type="submit">Guardar deuda <span>✓</span></button></form><div class="finance-debt-grid">${debts.map(d=>`<article class="panel finance-block"><div class="finance-debt-head"><div><div class="eyebrow">${safe(num(d.balance)>0&&d.dueDate&&d.dueDate<today()?'VENCIDA':d.status==='paid'?'LIQUIDADA':d.status==='paused'?'PAUSADA':'ACTIVA')}</div><h3>${safe(d.name)}</h3><p>${safe(d.concept)}</p></div><button type="button" class="finance-delete" data-delete="${safe(d.id)}" aria-label="Eliminar deuda">×</button></div><div class="finance-debt-stats"><span>Saldo <b>${moneyFormat(d.balance)}</b></span><span>Original <b>${moneyFormat(d.original)}</b></span><span>Mensualidad <b>${moneyFormat(d.monthlyPayment)}</b></span><span>Vence <b>${d.dueDate?dateNode(d.dueDate):'—'}</b></span></div>${d.balance>0?`<form class="finance-payment-form" data-debt="${safe(d.id)}"><label>Registrar abono<input name="amount" type="number" min="0.01" max="${safe(d.balance)}" step="0.01" required></label><label>Fecha<input name="date" type="date" value="${today()}" required></label><label>Forma de pago<select name="paymentMethod">${options(['Efectivo','Débito','Crédito','Transferencia','Domiciliación','Otro'],'Transferencia')}</select></label><label class="finance-check"><input name="makeExpense" type="checkbox" checked> Registrar también en gastos</label><label class="finance-wide">Nota<input name="note" maxlength="200"></label><button class="save-btn" type="submit">Guardar abono</button><small>El abono creará un gasto vinculado para el balance, y no se restará dos veces del disponible.</small></form>`:''}<h4>Historial de abonos</h4>${dataRows(debtPayments().filter(p=>p.debtId===d.id))}</article>`).join('')||empty('Registra una deuda para llevar control de sus abonos y vencimientos.')}</div>`;}
  function renderSavings(){const goals=all('goal');return `<div class="finance-toolbar"><div><div class="eyebrow">OBJETIVOS Y APORTACIONES</div><h2>Ahorros</h2></div><div class="finance-total">Acumulado ${moneyFormat(sum(goals,g=>num(g.balance)))}</div></div><form class="panel finance-form" id="goalForm"><h3>Crear objetivo de ahorro</h3><div class="finance-form-grid">${field('Nombre del objetivo','name','text','','maxlength="100"')}${field('Cantidad objetivo','target','number','','min="0.01" step="0.01"')}${field('Cantidad inicial','balance','number','0','min="0" step="0.01"')}${field('Fecha de inicio','startDate','date',today())}<label>Fecha objetivo<input name="targetDate" type="date"></label>${field('Aportación programada al mes','plannedMonthly','number','0','min="0" step="0.01"')}<label>Día de aportación<input name="contributionDay" type="number" min="1" max="28" value="1"></label><label class="finance-wide">Descripción<textarea name="notes" maxlength="300" rows="2"></textarea></label></div><button class="save-btn" type="submit">Guardar objetivo <span>✓</span></button></form><div class="finance-debt-grid">${goals.map(g=>{const percent=g.target>0?Math.min(100,Math.max(0,num(g.balance)/num(g.target)*100)):0;return `<article class="panel finance-block"><div class="finance-debt-head"><div><div class="eyebrow">OBJETIVO ${percent.toFixed(0)}% COMPLETADO</div><h3>${safe(g.name)}</h3><p>${safe(g.notes||'')}</p></div><button type="button" class="finance-delete" data-delete="${safe(g.id)}" aria-label="Eliminar objetivo">×</button></div><progress class="finance-progress" max="100" value="${percent}" aria-label="Avance del objetivo">${percent.toFixed(0)}%</progress><div class="finance-debt-stats"><span>Ahorrado <b>${moneyFormat(g.balance)}</b></span><span>Meta <b>${moneyFormat(g.target)}</b></span><span>Fecha objetivo <b>${g.targetDate?dateNode(g.targetDate):'—'}</b></span><span>Aporte mensual <b>${moneyFormat(g.plannedMonthly)}</b></span></div><form class="finance-savings-form" data-goal="${safe(g.id)}"><label>Tipo<select name="direction"><option value="deposit">Aportación</option><option value="withdrawal">Retiro</option></select></label><label>Importe<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Fecha<input name="date" type="date" value="${today()}" required></label><label>Nota<input name="note" maxlength="200"></label><button class="save-btn" type="submit">Guardar</button></form><h4>Historial</h4>${dataRows(savingsMoves().filter(m=>m.goalId===g.id))}</article>`;}).join('')||empty('Crea un objetivo y registra aportaciones o retiros para seguir su avance.')}</div>`;}
  function renderBudgets(){const budgets=all('budget');return `<div class="finance-toolbar"><div><div class="eyebrow">LÍMITES POR CATEGORÍA</div><h2>Presupuestos mensuales</h2></div><label class="finance-period">Mes<input type="month" data-period value="${safe(period)}"></label></div><form class="panel finance-form" id="budgetForm"><h3>Definir presupuesto</h3><div class="finance-form-grid"><label>Categoría<select name="category">${options(cats)}</select></label>${field('Límite del mes','limit','number','','min="0.01" step="0.01"')}<label>Mes<input type="month" name="month" value="${safe(period)}" required></label></div><button class="save-btn" type="submit">Guardar presupuesto</button></form><div class="finance-debt-grid">${budgets.filter(b=>b.month===period).map(b=>{const spent=sum(expenses().filter(e=>inMonth(e)&&e.category===b.category),val),pct=Math.min(100,spent/num(b.limit)*100);return `<article class="panel finance-block"><div class="finance-debt-head"><div><div class="eyebrow">${safe(b.month)}</div><h3>${safe(b.category)}</h3></div><button class="finance-delete" data-delete="${safe(b.id)}" aria-label="Eliminar">×</button></div><div class="finance-budget-line"><span>Gastado ${moneyFormat(spent)}</span><b>Límite ${moneyFormat(b.limit)}</b></div><progress class="finance-progress ${spent>b.limit?'over':''}" max="100" value="${pct}" aria-label="Uso del presupuesto">${pct.toFixed(0)}%</progress><small>Disponible del presupuesto: ${moneyFormat(num(b.limit)-spent)}</small></article>`;}).join('')||empty('No hay presupuestos definidos para este mes.')}</div>`;}
  const paymentOptions=(items,selected='')=>items.map(([value,label])=>`<option value="${safe(value)}" ${value===selected?'selected':''}>${safe(label)}</option>`).join('');
  const reminderRecords=()=>all('paymentReminder');
  const validPaymentReminder=r=>r&&typeof r.id==='string'&&typeof r.name==='string'&&r.name.trim().length>0&&Number(r.amount)>0&&Number.isFinite(dayDifference(r.dueDate))&&paymentFrequencies.some(([value])=>value===r.frequency)&&['pending','paid'].includes(r.status)&&Array.isArray(r.history||[])&&(r.history||[]).every(p=>p&&Number(p.amount)>0&&Number.isFinite(dayDifference(p.paidDate)));
  const dayDifference=(date,from=today())=>{const valid=value=>{const parts=String(value||'').split('-').map(Number);if(parts.length!==3||parts.some(n=>!n))return null;const time=Date.UTC(parts[0],parts[1]-1,parts[2]),check=new Date(time);return check.getUTCFullYear()===parts[0]&&check.getUTCMonth()===parts[1]-1&&check.getUTCDate()===parts[2]?time:null;},a=valid(date),b=valid(from);return a===null||b===null?NaN:Math.round((a-b)/86400000);};
  function reminderState(r){if(r.status==='paid')return 'Pagado';const days=dayDifference(r.dueDate);return days<0?'Vencido':days<=7?'Próximo a vencer':'Pendiente';}
  function remindersDashboard(){const items=reminderRecords(),pending=items.filter(r=>r.status!=='paid'),upcoming=pending.filter(r=>dayDifference(r.dueDate)>=0&&dayDifference(r.dueDate)<=7),overdue=pending.filter(r=>dayDifference(r.dueDate)<0),paidMonth=sum(items.flatMap(r=>r.history||[]).filter(p=>monthOf(p.paidDate)===period),p=>num(p.amount)),next=pending.slice().sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||'')).slice(0,5),editing=reminderRecords().find(r=>r.id===editingPaymentId)||null;return `<div class="finance-toolbar"><div><div class="eyebrow">AVISOS LOCALES · REQUIERE AGENDA ABIERTA</div><h2>Recordatorios de pago</h2></div><label class="finance-period">Mes pagado<input type="month" data-period value="${safe(period)}"></label></div><p class="payment-reminder-note">Los avisos se revisan al abrir o reactivar AGENDA y mientras permanece abierta. GitHub Pages y el navegador no pueden garantizar notificaciones con AGENDA cerrada.</p><div class="finance-metrics">${countCard('PAGOS PENDIENTES',pending.length)}${countCard('PRÓXIMOS A 7 DÍAS',upcoming.length)}${countCard('PAGOS VENCIDOS',overdue.length)}${card('PAGADO ESTE MES',paidMonth)}${card('IMPORTE PENDIENTE',sum(pending,r=>num(r.amount)))}</div><article class="panel finance-block"><div class="eyebrow">PRÓXIMOS CINCO VENCIMIENTOS</div>${next.length?next.map(r=>`<div class="finance-row"><time>${dateNode(r.dueDate)}</time><div><strong>${safe(r.name)}</strong><small>${safe(r.category)} · ${safe(reminderState(r))}</small></div><b>${moneyFormat(r.amount)}</b></div>`).join(''):empty('No hay pagos pendientes.')}</article>${paymentReminderForm(editing)}<section class="payment-reminder-list"><div class="finance-toolbar"><div><div class="eyebrow">OBLIGACIONES REGISTRADAS</div><h3>Pagos</h3></div><button type="button" class="media-folder-btn" data-payment-notifications>${'Notification'in window&&Notification.permission==='granted'?'Notificaciones activas':'Activar notificaciones'}</button></div><div class="finance-report-controls"><label>Categoría<select data-payment-filter-category><option value="">Todas</option>${options(paymentCategories)}</select></label><label>Estado<select data-payment-filter-state><option value="">Todos</option><option value="pending">Pendientes</option><option value="upcoming">Próximos</option><option value="overdue">Vencidos</option><option value="paid">Pagados</option></select></label><label>Desde<input type="date" data-payment-filter-from></label><label>Hasta<input type="date" data-payment-filter-to></label></div><div class="payment-reminder-cards">${renderReminderCards(items)}</div></section><dialog id="paymentPaidDialog" class="payment-paid-dialog"><form method="dialog" id="paymentPaidForm"><h3>Registrar pago realizado</h3><p id="paymentPaidName"></p><label>Fecha de pago<input name="paidDate" type="date" value="${today()}" required></label><label>Importe efectivamente pagado<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Observaciones <span class="optional">opcional</span><textarea name="notes" maxlength="500" rows="3"></textarea></label><div class="modal-actions"><button type="button" class="cancel-btn" data-close-payment>Cancelar</button><button type="submit" class="save-btn">Guardar pago</button></div></form></dialog>`;}
  function paymentReminderForm(record=null){const r=record||{};return `<form class="panel finance-form payment-reminder-form" id="paymentReminderForm" data-edit-id="${safe(r.id||'')}"><h3>${r.id?'Editar recordatorio':'Registrar pago'}</h3><div class="finance-form-grid">${field('Servicio o concepto','name','text',r.name||'','maxlength="120"')}${field('Importe','amount','number',r.amount??'','min="0.01" step="0.01"')}<label>Categoría<select name="category">${paymentOptions(paymentCategories.map(x=>[x,x]),r.category||'Otros')}</select></label>${field('Fecha de vencimiento','dueDate','date',r.dueDate||today())}<label>Frecuencia<select name="frequency">${paymentOptions(paymentFrequencies,r.frequency||'once')}</select></label><label>Método de pago<select name="paymentMethod">${options(['Efectivo','Débito','Crédito','Transferencia','Domiciliación','Otro'],r.paymentMethod||'Otro')}</select></label><label class="finance-wide">Observaciones<textarea name="notes" maxlength="500" rows="2">${safe(r.notes||'')}</textarea></label><label class="finance-check"><input type="checkbox" name="notificationsEnabled" ${r.notificationsEnabled===false?'':'checked'}> Activar notificaciones para este pago</label><fieldset class="payment-notice-days finance-wide"><legend>Avisar</legend>${[[7,'7 días antes'],[3,'3 días antes'],[1,'1 día antes'],[0,'El día del vencimiento']].map(([d,label])=>`<label><input type="checkbox" name="noticeDays" value="${d}" ${(r.noticeDays||[7,3,1,0]).includes(d)?'checked':''}> ${label}</label>`).join('')}<small>Los pagos vencidos pendientes se avisarán como máximo una vez al día.</small></fieldset></div><div class="payment-form-actions"><button class="save-btn" type="submit">${r.id?'Guardar cambios':'Guardar recordatorio'} <span>✓</span></button>${r.id?'<button class="cancel-btn" type="button" data-cancel-payment-edit>Cancelar edición</button>':''}</div></form>`;}
  function renderReminderCards(items){const category=$('[data-payment-filter-category]')?.value||'',state=$('[data-payment-filter-state]')?.value||'',from=$('[data-payment-filter-from]')?.value||'',to=$('[data-payment-filter-to]')?.value||'';const filtered=items.filter(r=>{const days=dayDifference(r.dueDate),rState=r.status==='paid'?'paid':days<0?'overdue':days<=7?'upcoming':'pending';return(!category||r.category===category)&&(!state||rState===state)&&(!from||r.dueDate>=from)&&(!to||r.dueDate<=to);}).sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||''));return filtered.map(r=>{const stateName=reminderState(r),stateClass=stateName==='Vencido'?'overdue':stateName==='Pagado'?'paid':stateName==='Próximo a vencer'?'upcoming':'pending';const history=(r.history||[]).slice().sort((a,b)=>(b.paidDate||'').localeCompare(a.paidDate||''));return `<article class="panel finance-block payment-reminder-card"><div class="payment-card-head"><div><span class="payment-state ${stateClass}">${safe(stateName)}</span><h3>${safe(r.name)}</h3><small>${safe(r.category)} · ${safe(paymentFrequencies.find(x=>x[0]===r.frequency)?.[1]||'Único')}</small></div><b>${moneyFormat(r.amount)}</b></div><div class="finance-debt-stats"><span>Vence <b>${dateNode(r.dueDate)}</b></span><span>Método <b>${safe(r.paymentMethod||'—')}</b></span></div>${r.notes?`<p>${safe(r.notes)}</p>`:''}<div class="payment-card-actions">${r.status!=='paid'?`<button type="button" class="save-btn" data-mark-payment="${safe(r.id)}">Marcar como pagado</button><button type="button" class="cancel-btn" data-snooze-payment="${safe(r.id)}">Posponer recordatorio</button>`:''}<button type="button" class="cancel-btn" data-edit-payment="${safe(r.id)}">Editar</button><button type="button" class="finance-delete" data-delete-payment="${safe(r.id)}" aria-label="Eliminar ${safe(r.name)}">×</button></div><details class="payment-history"><summary>Historial de pagos (${history.length})</summary>${history.length?history.map(p=>`<div class="payment-history-row"><span>${dateNode(p.paidDate)}</span><b>${moneyFormat(p.amount)}</b><small>${safe(p.notes||'')}</small></div>`).join(''):empty('Aún no hay pagos registrados.')}</details></article>`;}).join('')||empty(items.length?'No hay pagos que coincidan con esos filtros.':'Aún no tienes recordatorios de pago.');}
  function nextDueDate(date,frequency){const parts=String(date).split('-').map(Number);if(parts.length!==3||parts.some(n=>!n))return date;const [year,month,day]=parts;const monthSteps={monthly:1,bimonthly:2,quarterly:3,semiannual:6,annual:12};if(frequency==='weekly'||frequency==='biweekly'){const d=new Date(Date.UTC(year,month-1,day+(frequency==='weekly'?7:14)));return d.toISOString().slice(0,10);}const steps=monthSteps[frequency];if(!steps)return date;const targetMonth=month-1+steps,targetYear=year+Math.floor(targetMonth/12),targetMonthIndex=targetMonth%12,lastDay=new Date(Date.UTC(targetYear,targetMonthIndex+1,0)).getUTCDate();return `${targetYear}-${String(targetMonthIndex+1).padStart(2,'0')}-${String(Math.min(day,lastDay)).padStart(2,'0')}`;}
  function notificationMessage(r,kind,days){const name=r.name,amount=`Importe: ${moneyFormat(r.amount)}`;if(kind==='overdue')return {title:'PAGO VENCIDO',body:`${name} tiene un pago pendiente. ${amount}`};if(days===0)return {title:'PAGO HOY',body:`Hoy vence ${name}. ${amount}`};if(days===1)return {title:'RECORDATORIO',body:`Mañana vence ${name}. ${amount}`};return {title:'PRÓXIMO PAGO',body:`${name} vence dentro de ${days} días. ${amount}`};}
  async function deliverPaymentNotice(r,kind,days,key){const message=notificationMessage(r,kind,days),title=`${message.title} · AGENDA`;try{if(navigator.serviceWorker?.controller){const registration=await navigator.serviceWorker.ready;await registration.showNotification(title,{body:message.body,icon:'./icon-192.png',tag:`payment-${r.id}-${key}`,data:{url:'./'}});}else new Notification(title,{body:message.body,icon:'./icon-192.png',tag:`payment-${r.id}-${key}`});return true;}catch(error){console.warn('No se pudo mostrar el aviso de pago:',error);return false;}}
  async function checkPaymentReminders(){if(reminderCheckBusy||document.hidden||!db)return;reminderCheckBusy=true;try{const now=today(),updates=[];if(!('Notification'in window)||Notification.permission!=='granted')return;for(const original of reminderRecords()){if(original.status==='paid'||original.notificationsEnabled===false||!original.dueDate)continue;if(original.snoozeUntil&&now<original.snoozeUntil)continue;const days=dayDifference(original.dueDate,now),sent=new Set(original.sentNotifications||[]);let kind='',key='';if(days<0){kind='overdue';key=`${original.dueDate}:overdue:${now}`;}else if((original.noticeDays||[7,3,1,0]).includes(days)){kind=days===0?'due':'before';key=`${original.dueDate}:${days}`;}if(!kind||sent.has(key))continue;if(await deliverPaymentNotice(original,kind,days,key)){const copy={...original,sentNotifications:[...sent,key].slice(-120)};updates.push(copy);}}if(updates.length){const byId=new Map(updates.map(r=>[r.id,r])),next=records.map(r=>byId.get(r.id)||r);await commit(next);}}catch(error){console.warn('No se pudieron comprobar los avisos de pagos:',error);}finally{reminderCheckBusy=false;}}
  async function requestPaymentNotificationPermission(){if(!('Notification'in window))return notify('Este navegador no admite notificaciones. Los recordatorios se verán dentro de AGENDA.');const permission=await Notification.requestPermission();if(permission==='granted'){notice='Notificaciones activadas. Agenda comprobará los vencimientos al abrirse y mientras permanezca activa.';await checkPaymentReminders();}else notice='No se concedió permiso de notificaciones. Los pagos siguen guardados y visibles en AGENDA.';render();}
  function renderReports(){return `<div class="finance-toolbar"><div><div class="eyebrow">CONSULTAS, CALENDARIO Y EXPORTACIÓN</div><h2>Reportes y calendario</h2></div><label class="finance-period">Mes<input type="month" data-period value="${safe(period)}"></label></div><div class="finance-report-controls"><label>Periodo<select data-report-period><option value="day">Día</option><option value="week">Semana</option><option value="month" selected>Mes</option><option value="year">Año</option></select></label><label>Fecha de referencia<input type="date" data-report-date value="${safe(today())}"></label><label>Categoría<select data-category><option value="">Todas</option>${options(cats)}</select></label><label>Movimiento<select data-direction><option value="">Ingresos y gastos</option><option value="income">Ingresos</option><option value="expense">Gastos</option></select></label><button class="media-folder-btn" type="button" data-csv>Exportar CSV</button><button class="media-folder-btn" type="button" data-print>Imprimir reporte</button><button class="media-folder-btn" type="button" data-json-export>Respaldar finanzas JSON</button><button class="media-folder-btn" type="button" data-json-import>Restaurar JSON</button><input type="file" accept="application/json,.json" data-json-file hidden></div><div class="finance-columns"><article class="panel finance-block"><div class="eyebrow">INGRESOS CONTRA GASTOS</div><h3>Comparativo por mes</h3>${renderMonthlyBars()}</article><article class="panel finance-block"><div class="eyebrow">DISTRIBUCIÓN</div><h3>Gastos por categoría · ${safe(period)}</h3>${renderCategoryBars()}</article></div><article class="panel finance-block"><div class="finance-debt-head"><div><div class="eyebrow">MOVIMIENTOS FILTRADOS</div><h3>Detalle</h3></div><span data-filter-total></span></div><div id="financeReportRows"></div></article><article class="panel finance-block"><div class="eyebrow">FECHAS FINANCIERAS</div><h3>Calendario del mes</h3>${renderFinanceCalendar()}</article>`;}
  function renderMonthlyBars(){const yr=period.slice(0,4),sets=[];for(let m=1;m<=12;m++){const key=`${yr}-${String(m).padStart(2,'0')}`,inc=sum(incomes().filter(r=>monthOf(r.date)===key),val),exp=sum(expenses().filter(r=>monthOf(r.date)===key),val),scale=Math.max(inc,exp,1);sets.push(`<div class="finance-month-bar"><span>${new Intl.DateTimeFormat('es-MX',{month:'short'}).format(new Date(Number(yr),m-1,1))}</span><div><progress class="finance-mini-progress income" max="100" value="${inc/scale*100}" aria-label="Ingresos ${moneyFormat(inc)}"></progress><progress class="finance-mini-progress expense" max="100" value="${exp/scale*100}" aria-label="Gastos ${moneyFormat(exp)}"></progress></div><small>${moneyFormat(inc-exp)}</small></div>`);}return `<div class="finance-chart-legend"><i class="income"></i>Ingresos <i class="expense"></i>Gastos</div><div class="finance-bars">${sets.join('')}</div>`;}
  function renderCategoryBars(){const groups=cats.map(category=>({category,total:sum(expenses().filter(r=>inMonth(r)&&r.category===category),val)})).filter(x=>x.total>0).sort((a,b)=>b.total-a.total),max=Math.max(1,...groups.map(g=>g.total));return groups.length?groups.map(g=>`<div class="finance-category-bar"><span>${safe(g.category)}</span><progress class="finance-category-progress" max="100" value="${g.total/max*100}" aria-label="${safe(g.category)} ${moneyFormat(g.total)}"></progress><b>${moneyFormat(g.total)}</b></div>`).join(''):empty('Aún no hay gastos este mes.');}
  function renderFinanceCalendar(){const year=Number(period.slice(0,4)),month=Number(period.slice(5,7));const items=[...tx().filter(inMonth).map(r=>({...r,calLabel:r.direction==='income'?'Ingreso':'Gasto'})),...all('debt').filter(d=>d.dueDate&&monthOf(d.dueDate)===period&&num(d.balance)>0).map(d=>({id:d.id,date:d.dueDate,concept:d.name,amount:d.monthlyPayment,calLabel:'Vencimiento de deuda',direction:'pending'})),...all('goal').filter(g=>g.targetDate&&monthOf(g.targetDate)===period).map(g=>({id:g.id,date:g.targetDate,concept:g.name,amount:g.target,calLabel:'Meta de ahorro',direction:'pending'})),...all('goal').filter(g=>num(g.plannedMonthly)>0).map(g=>({id:g.id,date:`${period}-${String(Math.min(Number(g.contributionDay)||1,new Date(year,month,0).getDate())).padStart(2,'0')}`,concept:g.name,amount:g.plannedMonthly,calLabel:'Aportación programada',direction:'pending'}))].sort((a,b)=>a.date.localeCompare(b.date));return items.length?items.map(r=>`<div class="finance-calendar-row">${dateNode(r.date)}<span class="finance-calendar-dot ${r.direction}"></span><strong>${safe(r.calLabel)}</strong><span>${safe(r.concept)}</span><b>${moneyFormat(r.amount)}</b></div>`).join(''):empty('No hay fechas financieras este mes.');}
  const tabs=[['resumen','Resumen'],['movimientos','Movimientos'],['deudas','Deudas'],['ahorros','Ahorros'],['presupuestos','Presupuestos'],['pagos','Recordatorios de pago'],['reportes','Reportes']];
  function render(){if(!db){root.innerHTML='<section class="panel finance-block">Abriendo almacenamiento financiero local…</section>';return;}const bodies={resumen:renderSummary,movimientos:renderTransactions,deudas:renderDebts,ahorros:renderSavings,presupuestos:renderBudgets,pagos:remindersDashboard,reportes:renderReports};root.innerHTML=`<div class="finance-app"><nav class="finance-tabs" aria-label="Secciones financieras">${tabs.map(([key,label])=>`<button type="button" data-tab="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}</nav><div class="finance-local-note">Tus finanzas se guardan solo en este dispositivo y no participan en la sincronización de AGENDA. Descarga un respaldo JSON para transferirlas.</div>${notice?`<div class="finance-notice" role="status">${safe(notice)}</div>`:''}<div class="finance-content">${bodies[tab]()}</div><div class="finance-footer">Almacenamiento financiero local · IndexedDB</div></div>`;bind();if(tab==='pagos')checkPaymentReminders();}
  function notify(message){notice=message;render();}
  function bind(){root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;notice='';render();});root.querySelectorAll('[data-period]').forEach(i=>i.onchange=()=>{period=i.value||today().slice(0,7);render();});
    const reminderForm=$('#paymentReminderForm');if(reminderForm)reminderForm.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(reminderForm)),existing=records.find(r=>r.type==='paymentReminder'&&r.id===reminderForm.dataset.editId),amount=Number(x.amount),noticeDays=[...reminderForm.querySelectorAll('[name="noticeDays"]:checked')].map(input=>Number(input.value));if(!x.name.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(x.dueDate)||!Number.isFinite(dayDifference(x.dueDate))||amount<=0)return notify('Revisa el nombre, la fecha de vencimiento y el importe del pago.');const updated={...(existing||{}),id:existing?.id||id(),type:'paymentReminder',name:x.name.trim(),category:x.category,amount,dueDate:x.dueDate,frequency:x.frequency,paymentMethod:x.paymentMethod,notes:x.notes.trim(),notificationsEnabled:x.notificationsEnabled==='on',noticeDays,history:existing?.history||[],sentNotifications:existing?.dueDate===x.dueDate?(existing.sentNotifications||[]):[],status:existing?.status||'pending',createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};const next=existing?records.map(r=>r.id===existing.id?updated:r):[...records,updated];if(await savePaymentRecords(next,existing?'Recordatorio actualizado.':'Recordatorio de pago guardado.'))editingPaymentId=null;};
    const paidDialog=$('#paymentPaidDialog'),paidForm=$('#paymentPaidForm');if(paidForm)paidForm.onsubmit=async e=>{e.preventDefault();const targetId=paidForm.dataset.reminderId,record=records.find(r=>r.type==='paymentReminder'&&r.id===targetId),x=Object.fromEntries(new FormData(paidForm)),amount=Number(x.amount);if(!record||!(amount>0)||!/^\d{4}-\d{2}-\d{2}$/.test(x.paidDate)||!Number.isFinite(dayDifference(x.paidDate)))return notify('No se pudo validar la información del pago.');const history=[...(record.history||[]),{id:id(),dueDate:record.dueDate,paidDate:x.paidDate,amount,notes:x.notes.trim(),createdAt:new Date().toISOString()}],recurring=record.frequency!=='once',updated={...record,history,updatedAt:new Date().toISOString(),sentNotifications:[],snoozeUntil:''};if(recurring){updated.dueDate=nextDueDate(record.dueDate,record.frequency);updated.status='pending';}else updated.status='paid';const next=records.map(r=>r.id===record.id?updated:r);if(await savePaymentRecords(next,recurring?'Pago registrado; se creó el siguiente vencimiento.':'Pago registrado en el historial.'))paidDialog.close();};
    $('#paymentReminderForm')?.querySelector('[data-cancel-payment-edit]')?.addEventListener('click',()=>{editingPaymentId=null;render();});$('#paymentPaidDialog [data-close-payment]')?.addEventListener('click',()=>paidDialog.close());
    $('[data-payment-notifications]')?.addEventListener('click',requestPaymentNotificationPermission);
    root.querySelectorAll('[data-payment-filter-category],[data-payment-filter-state],[data-payment-filter-from],[data-payment-filter-to]').forEach(input=>{input.addEventListener('input',()=>{$('.payment-reminder-cards').innerHTML=renderReminderCards(reminderRecords());});input.addEventListener('change',()=>{$('.payment-reminder-cards').innerHTML=renderReminderCards(reminderRecords());});});
    root.querySelectorAll('[data-edit-payment]').forEach(button=>button.onclick=()=>{editingPaymentId=button.dataset.editPayment;render();$('#paymentReminderForm')?.scrollIntoView({behavior:'smooth',block:'start'});});
    root.querySelectorAll('[data-delete-payment]').forEach(button=>button.onclick=async()=>{const record=reminderRecords().find(r=>r.id===button.dataset.deletePayment);if(!record||!confirm(`¿Eliminar el recordatorio «${record.name}» y su historial de pagos?`))return;await savePaymentRecords(records.filter(r=>r.id!==record.id),'Recordatorio e historial eliminados.');});
    root.querySelectorAll('[data-mark-payment]').forEach(button=>button.onclick=()=>{const record=reminderRecords().find(r=>r.id===button.dataset.markPayment);if(!record)return;paidForm.dataset.reminderId=record.id;$('#paymentPaidName').textContent=`${record.name} · vencimiento ${record.dueDate}`;paidForm.elements.amount.value=String(record.amount);paidForm.elements.paidDate.value=today();paidForm.elements.notes.value='';paidDialog.showModal();});
    root.querySelectorAll('[data-snooze-payment]').forEach(button=>button.onclick=async()=>{const record=reminderRecords().find(r=>r.id===button.dataset.snoozePayment);if(!record)return;const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const defaultDate=`${tomorrow.getFullYear()}-${String(tomorrow.getMonth()+1).padStart(2,'0')}-${String(tomorrow.getDate()).padStart(2,'0')}`,until=prompt('Posponer avisos hasta esta fecha (AAAA-MM-DD):',defaultDate);if(until===null)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(until)||!Number.isFinite(dayDifference(until))||until<=today())return notify('La fecha para posponer debe ser posterior a hoy y tener formato AAAA-MM-DD.');const next=records.map(r=>r.id===record.id?{...r,snoozeUntil:until}:r);await savePaymentRecords(next,`Recordatorio pospuesto hasta ${until}.`);});
    const tform=$('#transactionForm');if(tform)tform.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(tform));if(!Number.isFinite(+x.amount)||+x.amount<=0)return notify('El importe debe ser mayor que cero.');records.push({id:id(),type:'transaction',direction:x.direction,concept:x.concept.trim(),amount:+x.amount,date:x.date,category:x.category,kind:x.kind,paymentMethod:x.paymentMethod,status:x.status,notes:x.notes.trim(),createdAt:new Date().toISOString()});await saveAndRefresh('Movimiento guardado.');};
    const dform=$('#debtForm');if(dform)dform.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(dform)),original=+x.original,balance=+x.balance;if(!(original>0)||balance<0||balance>original)return notify('Revisa los importes: el saldo debe estar entre cero y el importe original.');if(x.status==='paid'&&balance>0)return notify('Marca la deuda como liquidada solo cuando el saldo llegue a cero.');records.push({id:id(),type:'debt',name:x.name.trim(),concept:x.concept.trim(),original,balance,startDate:x.startDate,dueDate:x.dueDate,monthlyPayment:+x.monthlyPayment,frequency:x.frequency,interest:+x.interest,paymentsLeft:+x.paymentsLeft,status:x.status,notes:x.notes.trim(),createdAt:new Date().toISOString()});await saveAndRefresh('Deuda guardada.');};
    const gform=$('#goalForm');if(gform)gform.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(gform)),target=+x.target,balance=+x.balance;if(!(target>0)||balance<0)return notify('La meta debe ser positiva y el ahorro inicial no puede ser negativo.');records.push({id:id(),type:'goal',name:x.name.trim(),target,balance,startDate:x.startDate,targetDate:x.targetDate,plannedMonthly:+x.plannedMonthly,notes:x.notes.trim(),createdAt:new Date().toISOString()});await saveAndRefresh('Objetivo de ahorro guardado.');};
    const bform=$('#budgetForm');if(bform)bform.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(bform));if(+x.limit<=0)return notify('El límite debe ser mayor que cero.');const prior=records.find(r=>r.type==='budget'&&r.month===x.month&&r.category===x.category);if(prior)prior.limit=+x.limit;else records.push({id:id(),type:'budget',category:x.category,limit:+x.limit,month:x.month,createdAt:new Date().toISOString()});await saveAndRefresh('Presupuesto guardado.');};
    root.querySelectorAll('.finance-payment-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(form)),debt=records.find(d=>d.type==='debt'&&d.id===form.dataset.debt),amount=+x.amount;if(!debt||!(amount>0))return notify('No se encontró la deuda o el abono no es válido.');if(amount>num(debt.balance))return notify('El abono supera el saldo pendiente. Reduce el importe antes de continuar.');const paymentId=id();records.push({id:paymentId,type:'debtPayment',debtId:debt.id,concept:debt.name,amount,date:x.date,paymentMethod:x.paymentMethod,note:x.note.trim(),direction:'expense',createdAt:new Date().toISOString()});debt.balance=Math.max(0,Math.round((num(debt.balance)-amount)*100)/100);if(debt.balance===0){debt.status='paid';debt.paymentsLeft=0;}else if(debt.paymentsLeft>0)debt.paymentsLeft=Math.max(0,debt.paymentsLeft-1);if(x.makeExpense==='on'){const possible=records.find(r=>r.type==='transaction'&&r.direction==='expense'&&!r.debtPaymentId&&r.date===x.date&&num(r.amount)===amount);let linked=false;if(possible&&confirm(`Ya existe el gasto “${possible.concept}” por ${moneyFormat(amount)} en esa fecha. ¿Vincular este abono a ese gasto para evitar duplicarlo?`)){possible.debtPaymentId=paymentId;possible.notes=`${possible.notes||''}${possible.notes?' · ':''}Abono de deuda vinculado.`;linked=true;}if(!linked){records.push({id:id(),type:'transaction',direction:'expense',concept:`Abono deuda: ${debt.name}`,amount,date:x.date,category:'Otros',kind:'fixed',paymentMethod:x.paymentMethod,status:'paid',notes:`Pago vinculado ${paymentId}. No se duplica en el cálculo de disponible.`,debtPaymentId:paymentId,createdAt:new Date().toISOString()});}}await saveAndRefresh('Abono guardado y saldo actualizado.');});
    root.querySelectorAll('.finance-savings-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(form)),goal=records.find(g=>g.type==='goal'&&g.id===form.dataset.goal),amount=+x.amount;if(!goal||!(amount>0))return notify('El importe de la aportación debe ser mayor que cero.');if(x.direction==='withdrawal'&&amount>num(goal.balance))return notify('El retiro supera el ahorro acumulado en este objetivo.');const deposit=x.direction==='deposit';goal.balance=Math.max(0,Math.round((num(goal.balance)+(deposit?amount:-amount))*100)/100);records.push({id:id(),type:'savingsMove',goalId:goal.id,concept:goal.name,amount,date:x.date,direction:deposit?'deposit':'withdrawal',note:x.note.trim(),createdAt:new Date().toISOString()});await saveAndRefresh(deposit?'Aportación guardada.':'Retiro guardado.');});
    root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const record=records.find(r=>r.id===b.dataset.delete);if(!record)return;if(!confirm(`¿Eliminar ${record.type==='debt'?'esta deuda y su historial de abonos':record.type==='goal'?'este objetivo y sus movimientos':record.type==='debtPayment'?'este abono y actualizar su saldo':record.type==='savingsMove'?'este movimiento y actualizar el ahorro':'este registro'}?`))return;await removeRecord(record);});
    root.querySelectorAll('[data-search],[data-category],[data-direction],[data-from],[data-to]').forEach(i=>i.addEventListener('input',filterRows));root.querySelectorAll('[data-search],[data-category],[data-direction],[data-from],[data-to]').forEach(i=>i.addEventListener('change',filterRows));
    if($('[data-report-period]')){$('[data-report-period]').onchange=filterReport;$('[data-report-date]').onchange=filterReport;root.querySelectorAll('[data-category],[data-direction]').forEach(i=>i.onchange=filterReport);filterReport();}
    const csv=$('[data-csv]');if(csv)csv.onclick=exportCsv;const print=$('[data-print]');if(print)print.onclick=()=>window.print();const exp=$('[data-json-export]');if(exp)exp.onclick=exportJson;const imp=$('[data-json-import]');if(imp)imp.onclick=()=> $('[data-json-file]').click();const file=$('[data-json-file]');if(file)file.onchange=importJson;
  }
  async function savePaymentRecords(next,message){try{await commit(next);records=next;notice=message;render();return true;}catch(e){console.error(e);notify('No se pudo guardar el recordatorio. Los datos financieros anteriores se conservaron.');return false;}}
  async function saveAndRefresh(message){try{await commit(records);notice=message;render();}catch(e){console.error(e);notify('No se pudo guardar en este dispositivo. Comprueba el espacio del navegador.');}}
  function filterRows(){const search=$('[data-search]')?.value.trim().toLocaleLowerCase('es')||'',cat=$('.finance-filter [data-category]')?.value||'',direction=$('.finance-filter [data-direction]')?.value||'',from=$('[data-from]')?.value||'',to=$('[data-to]')?.value||'';let items=tx().filter(r=>(!search||`${r.concept} ${r.notes}`.toLocaleLowerCase('es').includes(search))&&(!cat||r.category===cat)&&(!direction||r.direction===direction)&&(!from||r.date>=from)&&(!to||r.date<=to));$('#financeTransactions').innerHTML=dataRows(items);bindDeleteOnly();}
  function bindDeleteOnly(){root.querySelectorAll('#financeTransactions [data-delete]').forEach(b=>b.onclick=async()=>{const record=records.find(r=>r.id===b.dataset.delete);if(record&&confirm('¿Eliminar este movimiento?'))await removeRecord(record);});}
  async function removeRecord(record){let next=records.filter(r=>r.id!==record.id);if(record.type==='debt'){const pids=records.filter(r=>r.type==='debtPayment'&&r.debtId===record.id).map(r=>r.id);next=next.filter(r=>!(r.type==='debtPayment'&&r.debtId===record.id)&&!(r.type==='transaction'&&pids.includes(r.debtPaymentId)));}else if(record.type==='goal')next=next.filter(r=>!(r.type==='savingsMove'&&r.goalId===record.id));else if(record.type==='debtPayment'){const debt=records.find(r=>r.type==='debt'&&r.id===record.debtId);if(debt){debt.balance=Math.min(num(debt.original),Math.round((num(debt.balance)+num(record.amount))*100)/100);if(debt.balance>0)debt.status='active';debt.paymentsLeft=num(debt.paymentsLeft)+1;}next=next.filter(r=>!(r.type==='transaction'&&r.debtPaymentId===record.id));}else if(record.type==='transaction'&&record.debtPaymentId){const payment=records.find(r=>r.type==='debtPayment'&&r.id===record.debtPaymentId),debt=payment&&records.find(r=>r.type==='debt'&&r.id===payment.debtId);if(payment&&debt){debt.balance=Math.min(num(debt.original),Math.round((num(debt.balance)+num(payment.amount))*100)/100);if(debt.balance>0)debt.status='active';debt.paymentsLeft=num(debt.paymentsLeft)+1;}next=next.filter(r=>r.id!==record.debtPaymentId);}else if(record.type==='savingsMove'){const goal=records.find(r=>r.type==='goal'&&r.id===record.goalId);if(goal){const delta=record.direction==='deposit'?-num(record.amount):num(record.amount);if(num(goal.balance)+delta<0)return notify('No puedes eliminar esta aportación: el saldo actual ya utilizó ese dinero.');goal.balance=Math.round((num(goal.balance)+delta)*100)/100;}}try{await commit(next);notice='Registro eliminado y saldos recalculados.';render();}catch(e){console.error(e);notify('No se pudo guardar el cambio.');}}
  function filterReport(){const periodType=$('[data-report-period]').value,date=$('[data-report-date]').value,cat=$('[data-category]')?.value||'',direction=$('[data-direction]')?.value||'';let from=date,to=date;if(periodType==='week'){const d=dateObj(date),offset=(d.getDay()+6)%7;d.setDate(d.getDate()-offset);from=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;d.setDate(d.getDate()+6);to=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}else if(periodType==='month'){from=date.slice(0,7)+'-01';const d=dateObj(from);d.setMonth(d.getMonth()+1);d.setDate(0);to=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}else if(periodType==='year'){from=date.slice(0,4)+'-01-01';to=date.slice(0,4)+'-12-31';}const items=tx().filter(r=>r.date>=from&&r.date<=to&&(!cat||r.category===cat)&&(!direction||r.direction===direction));$('#financeReportRows').innerHTML=dataRows(items);$('[data-filter-total]').textContent=`${items.length} registros · ${moneyFormat(sum(items.filter(r=>r.direction==='income'),val)-sum(items.filter(r=>r.direction==='expense'),val))}`;}
  function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@\-]/.test(s))s="'"+s;return `"${s.replaceAll('"','""')}"`;}
  function exportCsv(){const data=tx().filter(inMonth),lines=[['Fecha','Tipo','Concepto','Importe','Categoría','Clase','Forma de pago','Estado','Observaciones'],...data.map(r=>[r.date,r.direction==='income'?'Ingreso':'Gasto',r.concept,r.amount,r.category,r.kind,r.paymentMethod,r.status,r.notes])];const blob=new Blob(['\ufeff'+lines.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});download(blob,`agenda-movimientos-${period}.csv`);}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportJson(){const payload={format:'agenda-finanzas',version:1,exportedAt:new Date().toISOString(),records};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`agenda-finanzas-respaldo-${today()}.json`);}
  async function importJson(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>LIMIT)throw new Error('El respaldo supera el límite de 20 MB.');const data=JSON.parse(await file.text());if(data.format!=='agenda-finanzas'||data.version!==1||!Array.isArray(data.records)||data.records.length>100000)throw new Error('El archivo no es un respaldo de finanzas compatible.');const ids=new Set();for(const r of data.records){if(!r||typeof r.id!=='string'||ids.has(r.id)||!['transaction','debt','debtPayment','goal','savingsMove','budget','paymentReminder'].includes(r.type))throw new Error('El archivo contiene registros duplicados o inválidos.');ids.add(r.id);if(r.type==='paymentReminder'&&!validPaymentReminder(r))throw new Error('Hay un recordatorio de pago inválido en el archivo.');if(['transaction','debtPayment','savingsMove'].includes(r.type)&&(!(Number(r.amount)>0)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)))throw new Error('Hay movimientos con importes o fechas inválidos.');if(r.type==='debt'&&(Number(r.balance)<0||Number(r.original)<Number(r.balance)))throw new Error('Hay saldos de deuda inválidos.');if(r.type==='goal'&&(Number(r.balance)<0||Number(r.target)<=0))throw new Error('Hay objetivos de ahorro inválidos.');if(r.type==='budget'&&Number(r.limit)<=0)throw new Error('Hay presupuestos inválidos.');}if(!confirm(`Se restaurarán ${data.records.length} registros financieros. Esto reemplaza solo los datos financieros locales actuales; no modifica la agenda ni su sincronización. ¿Continuar?`))return;await commit(data.records);notice='Respaldo financiero restaurado.';render();}catch(e){alert(e.message||'No se pudo restaurar el respaldo.');}finally{event.target.value='';}}
  async function init(){try{db=await openDb();records=await readAll();render();await checkPaymentReminders();if(!reminderTimer)reminderTimer=window.setInterval(checkPaymentReminders,60000);if(!reminderListenersReady){document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkPaymentReminders();});window.addEventListener('focus',checkPaymentReminders);window.addEventListener('pageshow',checkPaymentReminders);reminderListenersReady=true;}}catch(e){console.error(e);root.innerHTML='<article class="panel finance-block">No se pudo abrir el almacenamiento financiero local. La información de AGENDA permanece intacta.</article>';}}
  function localizeDates(){root.querySelectorAll('[data-locale-date]').forEach(node=>{node.textContent=dateText(node.dataset.localeDate);});}
  window.addEventListener('agenda-language-changed',localizeDates);
  window.AgendaFinance={render,localizeDates,backupExport:async()=>{await init();return structuredClone(records);},backupRestore:async(incoming,mode)=>{if(!Array.isArray(incoming)||incoming.some(row=>!row||typeof row.id!=='string'||!['transaction','debt','debtPayment','goal','savingsMove','budget','paymentReminder'].includes(row.type)||(row.type==='paymentReminder'&&!validPaymentReminder(row))))throw new Error('Los registros financieros del respaldo no son válidos.');await init();const next=mode==='replace'?incoming:records.concat(incoming.filter(row=>!records.some(old=>old.id===row.id)));await commit(next);records=next;notice='Respaldo financiero restaurado.';render();return {count:next.length};}};
  init();
})();
